        type: "p",
        text: "Històricament, el paràmetre de GUID d'IFC a Revit era només de lectura, cosa que impedia als equips fixar-lo encara que volguessin. Les versions més noves de l'exportador el van fer de lectura i escriptura perquè el valor es pugui desar i reutilitzar — però encara cal activar el paràmetre correcte, perquè el comportament per defecte en algunes configuracions és regenerar-lo.",
