        text: "Hi ha una fallada relacionada que els scripts d'exportació fets a mida pateixen constantment. El primer caràcter d'un GlobalId d'IFC vàlid només pot codificar els valors 0–3 en l'alfabet de 6 bits, perquè un UUID de 128 bits empaquetat en 22 caràcters base64 deixa el primer sextet amb només dos bits significatius. Els scripts que agafen un UUID pla de 32 caràcters hexadecimals i el trunquen o el recodifiquen ingènuament produeixen un primer caràcter fora d'aquest rang.",
