        text: "El BCF existeix perquè les incidències sobrevisquin en sortir de la teva pantalla. Tot el seu valor rau en el viewpoint: una posició de càmera, una selecció i un comentari que, junts, fan que el receptor trigui deu segons a trobar el problema en lloc de deu minuts.",
