        type: "p",
        text: "També és, útilment, un validador del teu validador. Espais sense nom, tipus sense fabricant, components no assignats a cap espai: aquests buits arriben com a columnes en blanc que un gestor de manteniment veu d'un cop d'ull. Si una exportació COBie del teu model resultaria vergonyosa, el model no està a punt, per bé que sembli la geometria.",
