        text: "L'última línia és la que la gent es salta, i és la que et protegeix. Indicar per a què no serveix un contenidor no és una actitud defensiva: és la definició d'un nivell de necessitat d'informació, lliurada en l'únic moment en què algú realment la llegeix.",
