        type: "p",
        text: "La validesa d'esquema és el terra, no el sostre. Un fitxer en què cada element té Name='' i zero conjunts de propietats és perfectament vàlid segons l'esquema. Un model sense IfcElementQuantity, sense classificació i amb cada element físic col·locat directament a IfcSite en lloc d'una planta és perfectament vàlid segons l'esquema. Superar el verificador de buildingSMART vol dir que el fitxer STEP té el format correcte — no diu res sobre si les dades són útils.",
