        type: "p",
        text: "Els errors de geometria en IFC es divideixen en tres tipus principals: elements de volum zero (un perfil extrudit amb àrea zero), geometria sòlida no tancada (un sòlid amb forats a la superfície) i operacions booleanes fallides (una sostracció de buit que produeix un resultat no manifold). Són invisibles en visualitzar el model, perquè els renderitzadors els suavitzen; només es fan evidents quan la detecció de col·lisions o les eines de simulació intenten processar la geometria matemàticament.",
